package org.intelehealth.ezazi.stage3.dbimport android.util.Logimport org.intelehealth.ezazi.models.dto.EncounterDTOimport org.intelehealth.ezazi.stage3.models.DeliveryDetailsclass DeliveryDetailsRepository(    private val localDataSource: DeliveryDetailsLocalDataSource,    private val mapper: DeliveryDetailsObsMapper) {    private val TAG = "DeliveryRepository"    fun saveDeliveryDetails(encounterDTO: EncounterDTO, deliveryDetails: DeliveryDetails, creatorUuid: String, encounterTypeName: String): Boolean {        //  insert encounter- Women delivery outcome        val isEncounterInserted = localDataSource.insertEncounter(encounterDTO)        if (!isEncounterInserted) {            return false        }        val obsList = mapper.mapToObsList(encounterDTO.uuid, deliveryDetails, creatorUuid)        // Insert obs        val isObsInserted = localDataSource.saveDeliveryObsData(obsList)        Log.d(TAG, "saveDeliveryDetails: isObsInserted : "+isObsInserted)        Log.d(TAG, "saveDeliveryDetails: encounterTypeName : "+encounterTypeName)        if (!isObsInserted) return false        val resultFirstEncStage3 =localDataSource.createStage3FirstEncounter(encounterDTO.visituuid, encounterTypeName)        Log.d(TAG, "saveDeliveryDetails: resultFirstEncStage3 : "+resultFirstEncStage3)        // If data inserted        localDataSource.updateDecisionPendingFlagAndUnSyncVisitFlag(encounterDTO.visituuid, "false")        return true    }}